# Data engineering Fundamentals F3-F7: diagnostics (10 questions each, 90% to pass).
# Correct answer first; the app shuffles. concept = what a miss says to learn.
# Platform-neutral on purpose: nothing here depends on a particular Delta/Databricks version.
def Q(topic, id, concept, stem, options, why, table=None):
    q = {"id": f"de-{topic}-{id}", "concept": concept, "stem": stem, "options": options, "answer": 0, "why": why}
    if table: q["table"] = table
    return q

ORDERS = {"caption": "orders", "cols": ["order_id", "order_total"], "rows": [["A1", "100"], ["A2", "50"]]}
PAYMENTS = {"caption": "payments", "cols": ["order_id", "payment"], "rows": [["A1", "60"], ["A1", "40"], ["A2", "50"]]}

